where.if:
AND task_code = #{taskCode}
AND CHAR_LENGTH(task_code) = CHAR_LENGTH(#{taskCode})
AND CAST(task_code AS BINARY(256)) = CAST(#{taskCode} AS BINARY(256))

AND run_mode = #{runMode}
AND CHAR_LENGTH(run_mode) = CHAR_LENGTH(#{runMode})
AND CAST(run_mode AS BINARY(256)) = CAST(#{runMode} AS BINARY(256))

AND task_status = #{taskStatus}
AND CHAR_LENGTH(task_status) = CHAR_LENGTH(#{taskStatus})
AND CAST(task_status AS BINARY(256)) = CAST(#{taskStatus} AS BINARY(256))

AND severity_level = #{severityLevel}
AND CHAR_LENGTH(severity_level) = CHAR_LENGTH(#{severityLevel})
AND CAST(severity_level AS BINARY(256)) = CAST(#{severityLevel} AS BINARY(256))
